import RequestError from '#helpers/requestError';
import type { ChangeToken, CommunicatieId, CookieJar, FetchMethod, PolisId } from '#types';
import assert from 'assert';
import { resolve } from 'path';
import { Agent, type BodyInit, fetch, type RequestInit, type Response } from 'undici';

/** Query string-waarden. Arrays worden herhaalde keys: a=1&a=2 */
export type QueryValue = string | number | boolean;
export type Query = Record<string, QueryValue | QueryValue[]>;
export type Headers = Record<string, string>;

/** Waar `url` aan geplakt wordt in de functie {@link AxonContext.buildUrl} */
export type UrlBase =
    /** `.../Axon/services/rest/authenticated/<url>` — de normale REST-API. */
    | "service"
    /** `.../Axon/<url>` — voor auth/session en andere niet-REST endpoints. */
    | "root"
    /** `url` wordt ongewijzigd gebruikt. */
    | "absolute";

export type SendAxonOptions = {
    data?: unknown;
    changeToken?: string | null;
    /** De query die bij {@link AxonContext.builUrl} achter de URL wordt gevoegd */
    query?: Query;
    headers?: Headers;
    /**
     * Wordt doorgegeven aan {@link AxonContext.buildUrl} om een URL te genereren.
     * @default "Service"
     * */
    base?: UrlBase;
    /** Bij 403 één keer opnieuw proberen na `refreshAuth()`. Default `true`. */
    retry?: boolean;
    /** Wordt over de opgebouwde RequestInit gelegd. Ontsnappingsluik voor al het overige. */
    init?: Omit<RequestInit, "headers" | "method">;
};

const agent = new Agent({
    keepAliveTimeout: 10_000,
    keepAliveMaxTimeout: 60_000,
    connections: 30,
    headersTimeout: 30_000,
    bodyTimeout: 30_000,
});

/* ------------------ SESSION CLASS ----------------- */

/** Representeert een sessie met Axon, inclusief authenticatie. */
export default class AxonContext {
    #cookieJar: CookieJar = {};
    _clientId: string | null = null;
    #xsrfId: string | null = null;
    #refresh: Promise<void> | null = null;
    userId?: string;
    useTest;
    agent: Agent;
    logFetchValidator: (url: string, init: RequestInit) => boolean = () => false;

    constructor(useTest: boolean, connections: number) {
        this.useTest = useTest;
        this.agent = new Agent({
            keepAliveTimeout: 10_000,
            keepAliveMaxTimeout: 60_000,
            connections: connections,
            headersTimeout: 30_000,
            bodyTimeout: 30_000,
        });
    }

    // boundPolicy: PolisId | null = null;

    get #cookieHeader() {
        return Object.entries(this.#cookieJar).map(([k, v]) => `${k}=${v}`).join("; ");
    }

    /** De URL die bij het hoogste niveau van Axon voor a.s.r. hoort */
    get baseUrl() {
        return `https://asn-${this.useTest ? "pre-" : ""}intranet.keylanehosting.com/Axon` as const;
    }
    /** De URL die nodig is om met authenticatie CRUD-operaties in Axon te doen */
    get serviceUrl() {
        return `${this.baseUrl}/services/rest/authenticated` as const;
    }

    axonUrl(restUrl: string) {
        return `${this.baseUrl}/${restUrl}` as const;
    }

    /* ------------------ AUTHENTICATIE ----------------- */

    protected async login() {
        const home = process.env.HOME;
        assert(home, "No home path loaded in environment");
        process.loadEnvFile(resolve(home, "./.axon/.env.credentials"));
        assert(process.env.userId && process.env.password, `Please provide a value for 'userId' and 'password' in ${home}/.axon/.env.credentials`);
        this.userId = process.env.userId;

        await this.#fetchAssignCookies("Logon");

        const res = await this.sendAxon("POST", "Logon", {
            base: "root",
            retry: false,
            headers: { Referer: this.axonUrl("Logon") },
            data: new URLSearchParams({
                screen: "Logon",
                action: "Logon",
                userId: this.userId,
                password: process.env.password,
            }),
        });
        this.#assignCookies(res);
        return this;
    }

    readonly bootstrapTo = {
        url: (url: string) => this.bootstrap(url),
        polis: (id?: PolisId) => this.bootstrap("policies" + (id ?? `/${id}`)),
        ongekoppeldeCommunicatie: (id: CommunicatieId) => this.bootstrap(`other/unlinked-communications/${id}/browse-communication`),
        opgaven: (polisnummer: PolisId) => this.bootstrap(`policies/${polisnummer}/declarations`),
    };

    private async bootstrap(referer: string) {
        const res = await this.#fetchAssignCookies("admin-bootstrap.js", { accept: "*/*", Referer: this.axonUrl(referer) });
        const text = await res.text();
        const clientId = text.match(/Q-Client-Token",\s*"([^"]+)/)?.[1];
        const xsrfId = text.match(/Quinity-XSRF-Token",\s*"([^"]+)/)?.[1];
        if (!clientId || !xsrfId) throw new Error("Failed to extract policy tokens");
        this._clientId = clientId;
        this.#xsrfId = xsrfId;
        return this;
    }

    async #fetchAssignCookies(restUrl: string, headers: Headers = {}) {
        const res = await this.sendAxon("GET", restUrl, { base: "root", retry: false, headers });
        return this.#assignCookies(res);
    }

    #assignCookies(res: Response) {
        for (const cookie of res.headers.getSetCookie?.() ?? []) {
            const [first] = cookie.split(";");
            assert(first);
            const idx = first.indexOf("=");
            if (idx === -1) continue;
            this.#cookieJar[first.slice(0, idx).trim()] = first.slice(idx + 1).trim();
        }
        return res;
    }

    /** Vernieuwt de sessie. Parallelle aanroepen delen één request. */
    refreshAuth() {
        this.#refresh ??= this
            .sendAxon("POST", "services/auth/token/refresh", { base: "root", retry: false, data: {} })
            .then(res => { console.log(res); return res; })
            .then(res => { this.#assignCookies(res); })
            .finally(() => { this.#refresh = null; });
        return this.#refresh;
    }

    startSession() {
        return this.sendAxon("POST", "services/auth/session", { base: "root", retry: false })
            .then(res => this.#assignCookies(res));
    }

    /* -------------------- REQUESTS -------------------- */

    /**
     * Plakt de query aan de URL. Bij `base: "service"` eindigt de URL altijd op
     * een "?", ook zonder query (dat verwacht Axon).
     *
     * Arraywaarden in de query worden herhaald: `{status: ["open", "dicht"]}`
     * wordt `?status=open&status=dicht`.
     *
     * @param url De (rest)url die wordt gebruikt, zonder queryparams
     * @param query De query die achter de URL wordt geplakt
     * @param base Het soort base url dat wordt gebruikt.
     * - `"absolute"` - De hele URL wordt gebruikt
     * - `"root"` - De URL wordt achter {@link AxonContext.baseUrl} gevoegd
     * - `"service"` - De URL wordt achter {@link AxonContext.serviceUrl} gevoegd
     * @returns De volledige URL
     * @throws Als `url` eindigt op een "?"
     *
     * @example
     * De volgende code geeft als output https://asn-intranet.keylanehosting.com/Axon/claims?hideSearch=true
     * ```ts
     * session.buildUrl("claims", {hideSearch: true}, "root");
     * ```
     */
    private buildUrl(url: string, query: Query | undefined, base: UrlBase) {
        assert(!url.endsWith("?"), `Zet queryparams in 'query', niet in de url: ${url}`);

        const full =
            base === "absolute" ? url :
                base === "root" ? `${this.baseUrl}/${url}` :
                    `${this.serviceUrl}/${url}`;

        const params = new URLSearchParams();
        for (const [key, value] of Object.entries(query ?? {}))
            for (const v of Array.isArray(value) ? value : [value])
                params.append(key, String(v));

        const qs = params.toString();
        if (qs) return `${full}?${qs}`;
        return base === "service" ? `${full}?` : full;
    }

    /** Bepaalt de body en de bijbehorende content-type. */
    #buildBody(data: unknown, method: FetchMethod): [BodyInit | undefined, Headers] {
        if (data == null) return [undefined, method === "GET" ? {} : { "content-type": "application/json" }];
        if (typeof data === "string") return [data, {}];
        if (data instanceof URLSearchParams)
            return [data.toString(), { "content-type": "application/x-www-form-urlencoded" }];
        if (data instanceof FormData || data instanceof Uint8Array)
            return [data as BodyInit, {}];
        return [JSON.stringify(data), { "content-type": "application/json" }];
    }

    /**
     * De enige plek die daadwerkelijk `fetch` aanroept. Protected, zodat een
     * subclass een request kan sturen die niet in de methodes hieronder past.
     */
    protected async sendAxon(method: FetchMethod, url: string, opts: SendAxonOptions = {}): Promise<Response> {
        const { data, changeToken, query, headers, base = "service", retry = true, init } = opts;
        const [body, bodyHeaders] = this.#buildBody(data, method);

        const reqInit: RequestInit = {
            dispatcher: agent,
            ...init,
            method,
            ...(body !== undefined && { body }),
            headers: {
                accept: "application/json",
                ...bodyHeaders,
                ...headers,
                cookie: this.#cookieHeader,
                ...(this._clientId && { "x-quinity-client-identifier": this._clientId }),
                ...(this.#xsrfId && { "x-quinity-xsrf-token": this.#xsrfId }),
                ...(changeToken && { "if-match": changeToken }),
            },
        };

        const builtUrl = this.buildUrl(url, query, base);

        if (this.logFetchValidator(builtUrl, reqInit)) {
            console.log(`Sending ${method} to ${builtUrl}`);
            console.log("Headers:");
            this.#printTree(reqInit.headers);
            console.log("Body:");
            this.#printTree(data);
        }

        const res = await fetch(builtUrl, reqInit);

        if (res.status === 403 && retry) {
            console.debug("[DEBUG] Retrying")
            await this.refreshAuth();
            return this.sendAxon(method, url, { ...opts, retry: false });
        }

        if (!res.ok) throw await RequestError.from(reqInit, res);
        return res;
    }

    #printTree(body: unknown, prefix = "") {
        if (!body || typeof body !== "object") return;
        const entries = Object.entries(body);
        entries.forEach(([k, val], i) => {
            const isLast = i === entries.length - 1;
            const branch = isLast ? "`--" : "|--";
            const clean = typeof val === "object" ? "" : ` ${String(val).replace(/\n/g, " ").substring(0, 100)}`;
            console.log(`${prefix}${branch}${k}:${clean}`);
            if (val && typeof val === "object") this.#printTree(val, prefix + (isLast ? "   " : "|  "));
        });
    }

    /* ----------------- PUBLIEKE API ------------------- */
    // Elke methode neemt als laatste argument een `SendAxonOptions` mee, voor
    // headers, een andere base, of een RequestInit-overlay.

    /** Stuurt een GET-request naar Axon en retourneert de `Response` */
    getAxonRaw = (restUrl: string, query?: Query, opts?: SendAxonOptions) =>
        this.sendAxon("GET", restUrl, { ...opts, query });

    /** Stuurt een POST-request naar Axon en retourneert de `Response` */
    postAxonRaw = (restUrl: string, data?: unknown, query?: Query, opts?: SendAxonOptions) =>
        this.sendAxon("POST", restUrl, { ...opts, data, query });

    /** Stuurt een PUT-request naar Axon en retourneert de `Response`. `changeToken` gaat mee als If-Match. */
    putAxonRaw = (restUrl: string, changeToken: ChangeToken | null, data?: unknown, query?: Query, opts?: SendAxonOptions) =>
        this.sendAxon("PUT", restUrl, { ...opts, changeToken, data, query });

    /** Stuurt een DELETE-request naar Axon en retourneert de `Response`. `changeToken` gaat mee als If-Match. */
    deleteAxonRaw = (restUrl: string, changeToken: ChangeToken | null, query?: Query, opts?: SendAxonOptions) =>
        this.sendAxon("DELETE", restUrl, { ...opts, changeToken, query });

    /** Stuurt een GET-request naar Axon en parseert het `Response`-object naar JSON */
    getAxon = <T = unknown>(restUrl: string, query?: Query, opts?: SendAxonOptions) =>
        this.getAxonRaw(restUrl, query, opts).then(res => res.json() as Promise<T>);

    /** Stuurt een POST-request naar Axon en parseert het `Response`-object naar JSON */
    postAxon = <T = unknown>(restUrl: string, data?: unknown, query?: Query, opts?: SendAxonOptions) =>
        this.postAxonRaw(restUrl, data, query, opts).then(res => res.json() as Promise<T>);

    /** Stuurt een PUT-request naar Axon en parseert het `Response`-object naar JSON */
    putAxon = <T = unknown>(restUrl: string, changeToken: ChangeToken | null, data?: unknown, query?: Query, opts?: SendAxonOptions) =>
        this.putAxonRaw(restUrl, changeToken, data, query, opts).then(res => res.json() as Promise<T>);
}